type Args = Record<string, unknown>;
type Call = (target: string, args: Args) => Promise<unknown>;
/** Explicit whole-directory read for consumers that need every reachable identity. */
export async function readItems<T = unknown>(call: Call, target: string, args: Args = {}): Promise<T[]> {
  const items: T[] = [], seen = new Set<string>();
  let cursor: string | null | undefined;
  do {
    const page = await call(target, { ...args, ...(cursor ? { cursor } : {}) }) as { items: T[]; nextCursor?: string | null };
    items.push(...page.items);
    cursor = page.nextCursor;
    if (cursor && seen.has(cursor)) throw new Error("Directory cursor did not advance");
    if (cursor) seen.add(cursor);
  } while (cursor);
  return items;
}
